import{_ as l,o as e,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"CephFS Code Walkthrough: MDS Journal Machinery","description":"","frontmatter":{"title":"CephFS Code Walkthrough: MDS Journal Machinery","date":"2021-10-07T00:00:00.000Z","updated":"2021-10-08T00:00:00.000Z","tags":["Ceph","MDS","Journal","Metadata","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/CephFS_Code_Walkthrough_-_MDS_Journal_Machinery.md","filePath":"posts/2021/CephFS_Code_Walkthrough_-_MDS_Journal_Machinery.md","lastUpdated":1780459816000}'),r={name:"posts/2021/CephFS_Code_Walkthrough_-_MDS_Journal_Machinery.md"};function o(h,a,n,s,u,d){return e(),i("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-mds-日志结构与优化讨论" tabindex="-1">会议主题：Ceph MDS 日志结构与优化讨论 <a class="header-anchor" href="#会议主题-ceph-mds-日志结构与优化讨论" aria-label="Permalink to &quot;会议主题：Ceph MDS 日志结构与优化讨论&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>MDS 日志概述</strong>：</p><ul><li>MDS 日志是 CephFS 中 MDS（Metadata Server）的主要元数据变更记录者。</li><li>日志记录了近期元数据变更、客户端会话信息、导出导入状态、清除状态同步等。</li><li>MDS 日志作为循环缓冲区，在逻辑上无限扩展，但在物理上只占用有限的对象集。</li></ul></li><li><p><strong>客户端会话信息</strong>：</p><ul><li>MDS 记录新客户端连接的会话信息，这对故障恢复至关重要。</li><li>MDS 需要知道所有连接的客户端，以确保它们能够重新获取 caps 并重建状态。</li></ul></li><li><p><strong>日志结构与管理</strong>：</p><ul><li>日志对象大小通常为 4MB，满后 MDS 会移动到下一个对象。</li><li>日志指针用于指示当前日志的位置，便于灾难恢复或日志重置。</li><li>日志头部包含写入位置、过期位置和修剪位置等信息。</li></ul></li><li><p><strong>日志事件类型</strong>：</p><ul><li>日志事件包括子树映射、新会话信息、caps 更新等。</li><li>子树映射事件在每个新日志段开始时写入，以简化数据恢复。</li></ul></li><li><p><strong>日志优化</strong>：</p><ul><li>近期优化包括将打开文件表移出 MDS 日志，减少日志大小和提高故障转移时间。</li><li>未来可能的优化包括将递归 unlink RPC 移出日志，以及重新考虑客户端会话的日志记录方式。</li></ul></li><li><p><strong>代码实现讨论</strong>：</p><ul><li>讨论了 <code>osdc</code> 库中的日志管理代码，包括日志指针对象、日志头部对象和日志事件的处理。</li><li>强调了日志恢复和重放的逻辑，以及如何处理日志事件的持久化。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>需要进一步审查和可能合并 Jung 的 PR，该 PR 旨在将子树映射移出 MDS 日志，以解决性能和可扩展性问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续审查和测试 Jung 的 PR，确保其对 MDS 性能的提升。</li><li>考虑未来对 MDS 日志的其他潜在优化，如客户端会话管理和递归 unlink RPC 的处理。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在讨论了所有议题后结束，感谢所有参与者的参与，并约定下次会议时间。</li></ul>',12)])])}const c=l(r,[["render",o]]);export{p as __pageData,c as default};
